"""Summarize completed or partial exact-pullback experiments without promotion inference."""
import argparse
import csv
import json
from pathlib import Path
import numpy as np
import torch


def summarize(root):
    root=Path(root)
    status=json.loads((root/'status.json').read_text())
    rows=json.loads((root/'measurements.json').read_text()) if (root/'measurements.json').exists() else []
    selected_updates={}
    for checkpoint in root.glob('*_selected.pt'):
        # These checkpoints are generated by our own study, with NumPy metadata.
        metadata=torch.load(checkpoint,map_location='cpu',weights_only=False)
        selected_updates[checkpoint.stem.removesuffix('_selected')]=int(metadata['update'])
    original_rows=rows
    rows=[]
    for row in original_rows:
        if row['phase']=='development' and row['method'] in selected_updates:
            group=[r for r in original_rows if r['phase']=='development' and r['method']==row['method'] and r['mask']==row['mask']]
            ordinal=next(i for i,r in enumerate(group) if r is row)
            if ordinal//2*250!=selected_updates[row['method']]:continue
        rows.append(row)
    (root/'selected_updates.json').write_text(json.dumps(selected_updates,indent=2))
    keys=sorted(set((r['phase'],r['method'],r['mask'],r['trajectory']) for r in rows))
    summary=[]
    for phase,method,mask,trajectory in keys:
        subset=[r for r in rows if (r['phase'],r['method'],r['mask'],r['trajectory'])==(phase,method,mask,trajectory)]
        entry={'phase':phase,'method':method,'mask':mask,'trajectory':trajectory,'cases':sum(len(r['mpvpe_mm']) for r in subset)}
        for metric in ['mpvpe_mm','mpjpe_mm','visible_rad','apd_cm','seconds','peak_allocated','incremental_allocated','peak_reserved']:
            entry[metric]=float(np.mean([v for r in subset for v in r[metric]]))
        summary.append(entry)
    if summary:
        with (root/'summary.csv').open('w') as stream:
            writer=csv.DictWriter(stream,fieldnames=list(summary[0]));writer.writeheader();writer.writerows(summary)
    lines=['# Exact-pullback screening evidence','',f"Run state: {status['phase']}. Confirmation complete: {status['confirmation_complete']}.",'']
    promotion=root/'promotion.json'
    if promotion.exists():
        gates=json.loads(promotion.read_text())
        lines.append('Both student seeds passed all locked gates.' if gates['promoted'] else 'The selected recipe failed at least one locked gate; no promotion.')
    else:lines.append('No completed promotion decision is available.')
    lines+=['','Development summary rows use the selected checkpoint only; measurements.json retains all checkpoint evaluations in chronological order.','', 'Derivative fidelity is audited independently on 1,024 cached source points; each audit includes two random and two task covectors. These sampled checks do not prove covariance preservation.','', '| Student | Normalized VJP MSE | Mean VJP cosine |','|---|---:|---:|']
    for path in sorted(root.glob('*_audit.json')):
        audit=json.loads(path.read_text());lines.append(f"| {path.stem.removesuffix('_audit')} | {audit['normalized_mse']:.6g} | {audit['cosine']:.6g} |")
    lines+=['','Compare `development` with `zero_trajectory` rows in summary.csv to assess running-cost sensitivity. Checkpoints were selected solely using development hidden MPVPE; confirmation outcomes must not be used to retune coefficients.','', 'Timing is per 64-hypothesis optimization batch, including all configured outer iterations, rather than isolated network latency. CUDA allocated and reserved memory are reported separately. The frozen prior has only the original pilot training, and this validation study cannot establish the published AMASS protocol or broader generalization.']
    (root/'mechanism_report.md').write_text('\n'.join(lines)+'\n')

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('results');summarize(parser.parse_args().results)
